create table private.idempotency_commands (actor_id uuid not null, operation text not null, key uuid not null, request_hash text not null, response jsonb, created_at timestamptz not null default now(), primary key(actor_id, operation, key));
create table private.audit_log (id bigint generated always as identity primary key, actor_auth_user_id uuid, action text not null, aggregate_type text not null, aggregate_id uuid, club_id uuid, before_state jsonb, after_state jsonb, request_id uuid, created_at timestamptz not null default now());
create table private.outbox_events (id bigint generated always as identity primary key, topic text not null, aggregate_type text not null, aggregate_id uuid, club_id uuid, payload jsonb not null default '{}', created_at timestamptz not null default now(), published_at timestamptz);
create table private.rule_versions (domain text not null, version text not null, parameters jsonb not null, active_from timestamptz not null, retired_at timestamptz, primary key(domain, version));
create table private.calculation_runs (id uuid primary key default gen_random_uuid(), rule_version text not null, status text not null, checksum text, started_at timestamptz not null default now(), finished_at timestamptz);
create table private.trust_score_ledger (id uuid primary key default gen_random_uuid(), player_id uuid not null references public.players, reason_code text not null, delta numeric(8,2) not null, previous_score numeric(8,2) not null, current_score numeric(8,2) not null check(current_score between 0 and 100), source_id uuid, actor_auth_user_id uuid, rule_version text not null, request_id uuid not null unique, created_at timestamptz not null default now());
